    }
    for (let i = 0; i < GITHUB_PACKAGE_URLS.length; i++) {
      const url = GITHUB_PACKAGE_URLS[i];
      let timer = null;
      try {
        const ctrl = typeof AbortController !== "undefined" ? new AbortController() : null;
        if (ctrl) {
